public class Solution {
    public List<String[]> solveNQueens(int n) {
        List<String[]> result = new ArrayList<>();
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                board[i][j] = '.';
            }
        }
        solve(result, board, n, 0);
        return result;
    }

    private void solve(List<String[]> result, char[][] board, int n, int col) {
        if (col == n) {
            result.add(Arrays.copyOf(board, board.length));
            return;
        }
        for (int row = 0; row < n; row++) {
            if (isSafe(board, row, col)) {
                board[row][col] = 'Q';
                solve(result, board, n, col + 1);
                board[row][col] = '.';
            }
        }
    }

    private boolean isSafe(char[][] board, int row, int col) {
        for (int i = 0; i < col; i++) {
            if (board[row][i] == 'Q') {
                return false;
            }
        }
        int i = row, j = col;
        while (i >= 0 && j >= 0) {
            if (board[i][j] == 'Q') {
                return false;
            }
            i--; j--;
        }
        i = row; j = col;
        while (i < board.length && j >= 0) {
            if (board[i][j] == 'Q') {
                return false;
            }
            i++; j--;
        }
        return true;
    }
}
