public class Solution {
    public static boolean isSafe(int[] cols, int row) {
        int col = cols.length;
        for (int i = 0; i < col; i++) {
            if (cols[i] == row || Math.abs(i - col) == Math.abs(cols[i] - row)) {
                return false;
            }
        }
        return true;
    }

    public static int backtrack(int n, int[] cols) {
        if (cols.length == n) {
            return 1;
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (isSafe(cols, i)) {
                cols[cols.length] = i;
                count += backtrack(n, cols);
                cols[cols.length] = -1;
            }
        }

        return count;
    }

    public static int totalNQueens(int n) {
        int[] cols = new int[n];
        return backtrack(n, cols);
    }
}
