    q.push(beginWord);
    int steps = 1;

    while (!q.empty()) {
        int size = q.size();
        std::set<std::string> currentLevel;

        for (int i = 0; i < size; i++) {
            std::string currentWord = q.front();
            q.pop();
            if (currentWord == endWord) {
                return steps;
