    public int[] countSmaller(int[] nums) {
        int[] counts = new int[nums.length];
        mergeSort(nums, counts, 0, nums.length - 1);
        return counts;
    }

    private void mergeSort(int[] nums, int[] counts, int start, int end) {
        if (start >= end) {
            return;
        }
        int mid = (start + end) / 2;
        mergeSort(nums, counts, start, mid);
        mergeSort(nums, counts, mid + 1, end);
        merge(nums, counts, start, mid, end);
    }

    private void merge(int[] nums, int[] counts, int start, int mid, int end) {
        int[] left = new int[mid - start + 1];
        int[] right = new int[end - mid];
        for (int i = start; i <= mid; i++) {
            left[i - start] = nums[i];
        }
        for (int i = mid + 1; i <= end; i++) {
            right[i - mid - 1] = nums[i];
        }
        int i = 0, j = 0;
        for (int k = start; k <= end; k++) {
            if (i >= left.length) {
                nums[k] = right[j];
                counts[right[j]] += k - mid - 1;
                j++;
            } else if (j >= right.length) {
                nums[k] = left[i];
                counts[left[i]] += k - start;
                i++;
            } else if (left[i] <= right[j]) {
                nums[k] = left[i];
                counts[left[i]] += k - start;
                i++;
            } else {
                nums[k] = right[j];
                counts[right[j]] += k - mid - 1;
                j++;
