    def isConcatenated(self, word: str, wordDict: Set[str]) -> bool:
        n = len(word)
        dp = [False] * (n + 1)
        dp[0] = True

        for i in range(1, n + 1):
            for j in range(0, i):
                if dp[j] and wordDict.contains(word[j:i]):
                    dp[i] = True
                    break

        return dp[n]

    def findAllConcatenatedWords(self, words: List[str]) -> List[str]:
        wordDict = set(words)
        result = []
        for word in words:
            if self.isConcatenated(word, wordDict):
                result.append(word)

        return result
