public static List<Integer> findMode(TreeNode root) {
    if (root == null) return Collections.emptyList();
    Map<Integer, Integer> counts = new HashMap<>();
    InOrder(root, counts);
    int maxCount = Collections.max(counts.values());
    return counts.entrySet().stream()
            .filter(entry -> entry.getValue() == maxCount)
            .map(Map.Entry::getKey)
            .collect(Collectors.toList());
}

private static void InOrder(TreeNode node, Map<Integer, Integer> counts) {
    if (node == null) return;
    InOrder(node.left, counts);
    counts.put(node.val, counts.getOrDefault(node.val, 0) + 1);
    InOrder(node.right, counts);
}
