public class Solution {
    public int countArrangement(int n) {
        boolean[] visited = new boolean[n + 1];
        return helper(1, visited, n);
    }

    private int helper(int idx, boolean[] visited, int n) {
        if (idx > n) {
            return 1;
        }

        int count = 0;
        for (int i = 1; i <= n; i++) {
            if (!visited[i] && (idx % i == 0 || i % idx == 0)) {
                visited[i] = true;
                count += helper(idx + 1, visited, n);
                visited[i] = false;
            }
        }

        return count;
