public int removeBoxes(int[] boxes) {
    int[][][] dp = new int[boxes.length][boxes.length][100];
    for (int i = 0; i < boxes.length; i++) {
        for (int j = 0; j < boxes.length; j++) {
            for (int k = 0; k < 100; k++) {
                dp[i][j][k] = 0;
            }
        }
    }

    return dfs(0, boxes.length - 1, 0, boxes);
}

private int dfs(int l, int r, int k, int[] boxes) {
    if (l > r) return 0;

    if (dp[l][r][k] != 0) return dp[l][r][k];

    while (r > l && boxes[r] == boxes[r - 1]) {
        r--;
        k++;
    }

    dp[l][r][k] = (k + 1) * (k + 1) + dfs(l, r - 1, 0, boxes);

    for (int i = l; i < r; i++) {
        if (boxes[i] == boxes[r]) {
            dp[l][r][k] = Math.max(dp[l][r][k], dfs(l, i, k + 1, boxes) + dfs(i + 1, r - 1, 0, boxes));
        }
    }

    return dp[l][r][k];
}
