std::vector<int> findRedundantDirectedConnection(const std::vector<std::vector<int>>& edges) {
    std::vector<int> parent(edges.size() + 1, 0);
    int candidateA = 0, candidateB = 0;

    for (const auto& edge : edges) {
        if (parent[edge[1]] > 0) {
            candidateA = parent[edge[1]];
            candidateB = edge[1];
        } else {
            parent[edge[1]] = edge[0];
        }
    }

    for (int i = 1; i <= edges.size(); ++i) {
        int cycle = i;
        int steps = edges.size();
        while (parent[cycle] != 0 && steps > 0) {
            cycle = parent[cycle];
            steps--;
        }
        if (steps == 0) {
            if (!candidateA) {
                return {parent[i], i};
            } else {
                return {candidateA, candidateB};
            }
        }
    }

    return {candidateB, candidateA};
}
