    Set<String> groups = new HashSet<>();

    for (String word : words) {
        StringBuilder evens = new StringBuilder();
        StringBuilder odds = new StringBuilder();

        for (int i = 0; i < word.length(); ++i) {
            if (i % 2 == 0) evens.append(word.charAt(i));
