    if (strs.size() <= 1) return 0;
    std::sort(strs.begin(), strs.end());
    int min_diff = strs.back() - strs.front();
    for (int i = 1; i < strs.size(); i++) {
        int high = std::max(strs[i - 1] + k, strs.back() - k);
        int low = std::min(strs[i] - k, strs.front() + k);
        min_diff = std::min(min_diff, high - low);
    }
    return min_diff;
}
