int threeSumMulti(std::vector<int>& arr, int target) {
    const int MOD = 1000000007;
    int ans = 0;

    std::sort(arr.begin(), arr.end());
    int n = arr.size();

    for (int i = 0; i < n - 2; ++i) {
        int j = i + 1, k = n - 1;
        while (j < k) {
            int s = arr[i] + arr[j] + arr[k];
            if (s > target) {
                k--;
            } else if (s < target) {
                j++;
            } else {
                if (arr[j] != arr[k]) {
                    int left_count = right_count = 1;

                    while (j < n - 1 && arr[j] == arr[j + 1]) {
                        left_count += 1;
                        j++;
                    }

                    while (k > 0 && arr[k] == arr[k - 1]) {
                        right_count += 1;
                        k--;
                    }

                    ans += left_count * right_count;
                    ans %= MOD;
                    j++;
                    k--;
                } else {
                    ans += (k - j + 1) * (k - j) / 2;
                    ans %= MOD;
                    break;
                }
            }
        }
    }

    return ans;
}
