    }

    return count;
}

int dfs(int node, unordered_set<int>& visited, unordered_map<int, unordered_set<int>>& graph) {
    if (visited.find(node) != visited.end()) {
        return 0;
    }
    visited.insert(node);
    int size = 1;
    for (int neighbor : graph[node]) {
        size += dfs(neighbor, visited, graph);
    }
    return size;
}
