public class Solution {
    public int numSquarefulPerms(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }
        int[] arr = new int[set.size()];
        int i = 0;
        for (int num : set) {
            arr[i++] = num;
        }
        Arrays.sort(arr);
        int[][] dp = new int[arr.length][arr.length];
        for (int i = 0; i < arr.length; i++) {
            for (int j = 0; j < arr.length; j++) {
                dp[i][j] = -1;
            }
        }
        return dfs(arr, 0, 0, dp);
    }

    private int dfs(int[] arr, int idx, int sum, int[][] dp) {
        if (idx == arr.length) {
            return sum == 0 ? 1 : 0;
        }
        if (dp[idx][sum] != -1) {
            return dp[idx][sum];
        }
        int count = 0;
        for (int i = idx; i < arr.length; i++) {
            if (sum + arr[i] == 0) {
                count += dfs(arr, i + 1, 0, dp);
            } else if (isSquare(sum + arr[i])) {
                count += dfs(arr, i + 1, sum + arr[i], dp);
            }
        }
        dp[idx][sum] = count;
        return count;
    }

    private boolean isSquare(int n) {
        int sqrt = (int) Math.sqrt(n);
        return sqrt * sqrt == n;
    }
}
