        int rootx = find.apply(x);
        int rooty = find.apply(y);
        if (rootx != rooty) {
            if (rank[rootx] > rank[rooty]) {
                int temp = rootx;
                rootx = rooty;
                rooty = temp;
            }
            parent[rootx] = rooty;
            if (rank[rootx] == rank[rooty])
                rank[rooty]++;
