public class JobScheduling {
    public static int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        Job[] jobs = new Job[startTime.length];
        for (int i = 0; i < startTime.length; i++) {
            jobs[i] = new Job(startTime[i], endTime[i], profit[i]);
        }
        Arrays.sort(jobs, Comparator.comparingInt(Job::getEndTime));
        int[] dp = new int[startTime.length];
        dp[0] = jobs[0].profit;
        for (int i = 1; i < startTime.length; i++) {
            int L = latestNonConflict(i, dp);
            dp[i] = Math.max(dp[i - 1], (0 if L == -1 else dp[L]) + jobs[i].profit);
        }
        return dp[startTime.length - 1];
    }

    private static int latestNonConflict(int index, int[] dp) {
        int startTimeToFind = dp[index].endTime;
        int index = Arrays.binarySearch(dp, new Job(startTimeToFind, 0, 0), Comparator.comparingInt(Job::getStartTime));
        if (index < 0) {
            return -1;
        }
        return index;
    }

    private static class Job {
