    int steps = 0;

    while (!q.empty()) {
        for (int i = 0; i < q.size(); i++) {
            int x, y, steps, k_remaining;
            tie(x, y, steps, k_remaining) = q.front();
            q.pop();
            if (x == m - 1 && y == n - 1) {
                return steps;
            }
            for (auto& move : moves) {
                int new_x = x + move.first, new_y = y + move.second;
                if (0 <= new_x && new_x < m && 0 <= new_y && new_y < n) {
                    int new_k_remaining = k_remaining - grid[new_x][new_y];
                    if (new_k_remaining >= 0 && !visited[new_x][new_y][new_k_remaining]) {
                        visited[new_x][new_y][new_k_remaining] = true;
                        q.push({new_x, new_y, steps + 1, new_k_remaining});
                    }
                }
            }
        }
        steps++;
    }

    return -1;
}
