    board[n-1][n-1] = '0';
    cnt[n-1][n-1] = 1;

    for (int i = n-1; i >= 0; i--) {
        for (int j = n-1; j >= 0; j--) {
            if (board[i][j] != 'X') {
                vector<pair<int, int>> neighbors = {{i-1, j}, {i, j-1}, {i-1, j-1}};
                for (auto& neighbor : neighbors) {
                    if (neighbor.first >= 0 && neighbor.second >= 0) {
                        if (dp[i][j] < dp[neighbor.first][neighbor.second] + stoi(board[i][j])) {
                            dp[i][j] = dp[neighbor.first][neighbor.second] + stoi(board[i][j]);
                            cnt[i][j] = cnt[neighbor.first][neighbor.second];
