std::vector<std::vector<std::string>> displayTable(const std::vector<std::vector<std::string>>& orders) {
    std::unordered_map<int, std::unordered_map<std::string, int>> tables;
    std::unordered_set<std::string> foodSet;

    for (const auto& order : orders) {
        int tableNumber = std::stoi(order[1]);
        std::string foodItem = order[2];
        tables[tableNumber][foodItem] += 1;
        foodSet.insert(foodItem);
    }

    std::vector<std::string> foodList(foodSet.begin(), foodSet.end());
    std::sort(foodList.begin(), foodList.end());

    std::vector<std::vector<std::string>> result;
    result.emplace_back(1 + foodList.size(), "Table");
    for (const auto& food : foodList) {
        result.emplace_back();
        result.back().push_back(food);
    }

    for (const auto& table : tables) {
        result.emplace_back();
        result.back().push_back(std::to_string(table.first));
        for (const auto& food : foodList) {
            result.back().push_back(std::to_string(table.second[food]));
        }
    }

    return result;
}
