int maxCandies(std::vector<std::vector<int>>& status, std::vector<int>& candies, std::vector<int>& keys, std::vector<std::vector<int>>& containedBoxes, std::vector<int>& initialBoxes) {
    int max_candies = 0;
    std::set<int> visited;
    std::queue<int> to_process;

    for (int box : initialBoxes) {
        to_process.push(box);
    }

    while (!to_process.empty()) {
        int box = to_process.front();
        to_process.pop();

        if (visited.find(box) != visited.end()) {
            continue;
