    public static double countCombinations(int[] balls, int[] combinations, int currBall) {
        double totalCombinations = 1;
        for (int i = 0; i < currBall; i++) {
            totalCombinations *= factorial(balls[i] + combinations[i]) / (factorial(balls[i]) * factorial(combinations[i]));
        }

        return totalCombinations;
    }

    public static int dfs(int[] balls, int[] combinations, int currBall) {
        if (currBall == balls.length) {
            if (combinations[combinations.length - 1] == combinations[0]) {
                return (int) countCombinations(balls, combinations, currBall);
            } else {
                return 0;
            }
        }

        int result = 0;
        for (int i = 0; i <= balls[currBall]; i++) {
            combinations[currBall] = i;
            result += dfs(balls, combinations, currBall + 1);
        }

        return result;
    }

    public static double getProbability(int[] balls) {
        int sumBalls = 0;
        for (int ball : balls) {
            sumBalls += ball;
        }

        int totalCombinations = 1;
        for (int ball : balls) {
            totalCombinations *= factorial(ball);
        }

        int[] combinations = new int[balls.length];
        return dfs(balls, combinations, 0) / (double) totalCombinations;
    }

