            if s[i].isdigit():
                nodes.append(TreeNode(int(s[i])))
            elif s[i] == '(':
                ops.append(s[i])
            elif s[i] == ')':
                while ops[-1] != '(':
                    self.process(nodes, ops)
                ops.pop()
            else:
                while ops and self.precedence(ops[-1], s[i]):
                    self.process(nodes, ops)
                ops.append(s[i])
        while ops:
            self.process(nodes, ops)
        return nodes[0]

    def precedence(self, a, b):
        if a == '(': return False
        if b == '(' or b == ')': return True
        if (a == '*' or a == '/') and (b == '+' or b == '-')) return True
        return False

    def process(self, nodes, ops):
        right = nodes.pop()
        left = nodes.pop()
        oper = TreeNode(ops.pop())
        oper.left = left
        oper.right = right
        nodes.append(oper)
