            return false;
        }

        Deque<TreeNode> q = new LinkedList<>();
        q.add(root);
        int level = 0;

        while (!q.isEmpty()) {
            int size = q.size();
            int prevVal = 0;

            if (level % 2 == 0) {
                prevVal = 10000001;
            } else {
                prevVal = -10000001;
