    public static int makeStringSorted(String s) {
        int mod = 1000000007;
        int n = s.length();
        int[] fact = new int[n + 1];
        int[] inv = new int[n + 1];
        fact[0] = 1;
        inv[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % mod;
            inv[i] = (inv[i - 1] * (mod - mod / i)) % mod;
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            int lessThan = 0;
            for (int j = i + 1; j < n; j++) {
                if (s.charAt(j) < s.charAt(i)) {
                    lessThan++;
                }
            }
            ans = (ans + lessThan * fact[n - i - 1]) % mod;
        }
        return ans;
    }
}
