public int minSpaceWastedKResizing(int[] nums, int k) {
    int n = nums.length;
    int[][] dp = new int[n + 1][k + 1];
    int[] sumNums = new int[n + 1];
    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        sumNums[i] = sumNums[i - 1] + nums[i - 1];
        int maxVal = nums[i - 1];
        for (int j = i - 1; j >= 0; j--) {
            maxVal = Math.max(maxVal, nums[j]);
            int waste = maxVal * (i - j) - (sumNums[i] - sumNums[j]);
            for (int c = 0; c <= k; c++) {
                dp[i][c + 1] = Math.min(dp[i][c + 1], dp[j][c] + waste);
            }
        }
    }

    return dp[n][k];
}
