class Solution {
public:
    ListNode* reverseGroup(ListNode* head, int k) {
        if (!head || k == 1) {
            return head;
        }
        ListNode* prev = nullptr;
        ListNode* cur = head;
        for (int i = 0; i < k; i++) {
            ListNode* next = cur->next;
            cur->next = prev;
            prev = cur;
            cur = next;
        }
        head->next = cur;
        return prev;
    }

    ListNode* reverseEvenGroups(ListNode* head) {
        ListNode* dummy = new ListNode(0);
        dummy->next = head;
        ListNode* prev = dummy;
        int n = 0;
        ListNode* cur = head;
        while (cur) {
            n++;
            cur = cur->next;
        }
        int i = 1, k = 1;
        while (n >= 0 && k <= n) {
            if (i % 2 == 0) {
                ListNode* tail = prev->next;
                ListNode* next = prev->next;
                for (int j = 0; j < k; j++) {
                    next = next->next;
                }
                prev->next = reverseGroup(tail, k);
                tail->next = next;
            }
            n -= k;
            for (int j = 0; j < k; j++) {
                prev = prev->next;
            }
            i++;
            k += i;
        }
        return dummy->next;
    }
};
