public int largestEvenSum(int[] nums, int k) {
    List<Integer> evens = new ArrayList<>();
    List<Integer> odds = new ArrayList<>();

    for (int num : nums) {
        if (num % 2 == 0) {
            evens.add(num);
        } else {
            odds.add(num);
        }
    }

    Collections.sort(evens, Collections.reverseOrder());
    Collections.sort(odds, Collections.reverseOrder());

    int sum = 0;
    for (int i = 0; i < k; i++) {
        if (!evens.isEmpty()) {
            sum += evens.remove(0);
        }
    }

    for (int i = 0; i < k - 1; i += 2) {
        if (!odds.isEmpty()) {
            int first = odds.remove(0);
            if (!odds.isEmpty()) {
                int second = odds.remove(0);
                sum += first + second;
            }
        }
    }

    return sum % 2 == 0 ? sum : -1;
}
