    public int deleteEdgesToBalanceTree(int[] nums, int[][] edges) {
        int n = nums.length;
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] e : edges) {
            graph.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
            graph.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
        }

        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % 2 != 0) {
            return 0; // It is impossible to split the tree fairly.
        }

        List<Integer> result = new ArrayList<>();
        dfs(0, -1, nums, graph, total, result);
        return result.size() - 1;
    }

    private int dfs(int node, int parent, int[] nums, Map<Integer, List<Integer>> graph, int total, List<Integer> result) {
        int totalSum = nums[node];
        for (int neighbor : graph.getOrDefault(node, Collections.emptyList())) {
            if (neighbor != parent) {
                totalSum += dfs(neighbor, node, nums, graph, total, result);
            }
        }
        if (totalSum == total / 2) {
            result.add(1);
            return 0;
        }
        return totalSum;
    }
