    int[][] dp = new int[61][1001];
    dp[0][0] = 1;
    int idx = 0;
    for (Map.Entry<Integer, Integer> entry : counter.entrySet()) {
        idx++;
        for (int sq = 0; sq < 61; sq++) {
            for (int ns = 0; ns < 1001 - entry.getValue(); ns++) {
                dp[idx][ns + entry.getValue()] += dp[idx - 1][ns] * ((1 << entry.getValue()) - 1) % MOD;
                dp[idx][ns + entry.getValue()] %= MOD;
                dp[idx][ns] += dp[idx - 1][ns];
