import java.util.*;

public class Solution {
    public int minEdgesToCollectCoins(int[] coins, int[][] edges) {
        int n = coins.length;
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
