        Arrays.setAll(ids, i -> i);
        Arrays.sort(ids, (i, j) -> -Integer.compare(w[i], w[j]));

        long ans = 0;
        for (int i = 0; i < Math.min(lb, n); i++) ans += w[ids[i]];
        out.println(ans);
