        for (int i = 1; i <= n; ++i) {
            if (i == n || hash1[i] != hash1[p1]) {
                long cur = i - p1;
                ans += cur * (cur - 1) / 2;
                p1 = i;
            }
            if (i == n || hash2[i] != hash2[p2]) {
                long cur = i - p2;
                ans += cur * (cur - 1) / 2;
                p2 = i;
            }
        }
        cout.println(ans);
        cout.flush();
    } 
