        if (n < 4 || k > 3 || k == 1 || (k == 2 && n == 4)) {
            System.out.println("-1");
            return;
        }

        // si k=2
        if (k == 2) {
            System.out.println(n - 1);
            for (int i = 1; i < n; i++) {
                System.out.println(i + " " + (i + 1));
            }
            return;
        }

        // si k=3 y n=4
        if (n == 4) {
            System.out.println(n - 1);
            System.out.println("1 2");
            System.out.println("2 3");
            System.out.println("3 4");
