#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int day;
    std::cin >> day;

    std::vector<std::string> situations(day);
    for (int i = 0; i < day; i++) {
        std::cin >> situations[i];
    }

    std::vector<std::vector<int>> dp(day + 1, std::vector<int>(3, 1000000000));

    // Base Case:
    for (int j = 0; j < 3; j++) {
        dp[0][j] = 0;
    }

    // Inductive Step:
    for (int i = 1; i <= day; i++) {
        // 0: rest
        dp[i][0] = 1 + std::min(dp[i - 1][0], dp[i - 1][1], dp[i - 1][2]);
        // 1: gym
        dp[i][1] = std::min(dp[i - 1][0], dp[i - 1][2]);
        // 2. contest
        dp[i][2] = std::min(dp[i - 1][0], dp[i - 1][1]);

        if (situations[i - 1] == "0") {
            dp[i][1] = 1000000000;
            dp[i][2] = 1000000000;
        } else if (situations[i - 1] == "1") {
            dp[i][1] = 1000000000;
        } else if (situations[i - 1] == "2") {
            dp[i][2] = 1000000000;
        }
    }

    std::cout << std::min(dp[day][0], dp[day][1], dp[day][2]) << std::endl;

    return 0;
}
