        int n = graph.length;
        visited = new boolean[n];
        stack = new Stack<>();
        time = 0;
        lowlink = new int[n];
        components = new ArrayList<>();

        for (int u = 0; u < n; u++) {
            if (!visited[u]) {
                dfs(u);
            }
        }

        return components;
    }

    static void dfs(int u) {
        lowlink[u] = time++;
        visited[u] = true;
        stack.add(u);
        boolean isComponentRoot = true;

        for (Edge edge : graph[u]) {
            int v = edge.to;
            if (!visited[v]) {
                dfs(v);
            }
            if (lowlink[u] > lowlink[v]) {
                lowlink[u] = lowlink[v];
                isComponentRoot = false;
            }
        }

        if (isComponentRoot) {
            List<Integer> component = new ArrayList<>();
            while (true) {
                int x = stack.pop();
                component.add(x);
                lowlink[x] = Integer.MAX_VALUE;
                if (x == u) {
                    break;
                }
            }
            components.add(component);
        }
    }

    static int log(long a, long b) {
        if (a == 0 || a == 1) {
            return 0;
        }
        if (a == b) {
            return 1;
        }
        int log = 0;
        while (a > 0) {
            a /= b;
            log++;
        }
        return log;
    }

    static long pow(long a, long b) {
        if (a == 0) {
            return 0;
        }
        if (a == 1) {
            return 1;
        }
        long answer = 1;
        for (long i = 0; i < b; i++) {
            answer *= a;
        }
        return answer;
    }
}

