	}

	public static long getNewRatio(long n, long maxRatio) {
		long result = 1;
		for (Long i = 1l; i * i <= n; i++)
			if (n % i == 0) {
				if (n / i <= maxRatio)
					return n / i;
				else if (i <= maxRatio && i > result)
					result = i;
			}
		return result;
	}

