public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long sum = 0;
        ArrayList<ArrayList<Edge>> es = new ArrayList<>();
        es.add(new ArrayList<>());
        for (int i = 0; i < n - 1; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            int w = sc.nextInt();
            es.get(x).add(new Edge(x, y, w));
            es.get(y).add(new Edge(y, x, w));
            sum += w;
        }
        System.out.println(sum * 2 - dfs(1, -1));
    }

    static long dfs(int u, int p) {
        long ret = 0;
        for (Edge e : es.get(u)) {
            if (e.b == p) {
                ret = Math.max(0, ret);
            } else {
                ret = Math.max(ret, dfs(e.b, u) + e.w);
            }
        }
        return ret;
    }

    static class Edge {
        int a;
        int b;
        int w;

        public Edge(int a, int b, int w) {
            this.a = a;
            this.b = b;
            this.w = w;
        }
