public class E
{
	BufferedReader in;
	PrintStream out;
	StringTokenizer tok;
	public E() throws NumberFormatException, IOException
	{
		in = new BufferedReader(new InputStreamReader(System.in));
		//in = new BufferedReader(new FileReader("in.txt"));
		out = System.out;
		run();
	}
	int bs(List<Integer> a, int x)
	{
		int l = 0;
		int h = a.size()-1;
		while(l<=h)
		{
			int m = (l+h)/2;
			if(a.get(m) < x)l = m+1;
			else h = m-1;
		}
		return l;
	}
	void run() throws NumberFormatException, IOException
	{
		long k = nextLong();
		long b = nextLong();
		int n = nextInt();

		long[] dig = new long[n];
		long[] s = new long[n+1];
		TreeMap<Long,List<Integer>> r = new TreeMap<Long,List<Integer>>();
		long c = 0;
		for(int i = 0; i < n; i++)
		{
			dig[i] = nextLong();
			c+=dig[i];
			c%=(k-1);
			if(r.containsKey(c))
			{
				List<Integer> l = r.get(c);
				l.add(i);
			}
			else
			{
				List<Integer> l = new ArrayList<Integer>();
				l.add(i);
				r.put(c, l);
			}
			s[i+1] = c;
		}
		long ans = 0;
		long zeros = 0;
		for(int i =0; i < n; i++)
		{
			List<Integer> l = r.get((b+s[i])%(k-1));
			if(l==null) continue;
			int p = bs(l,i);
			if(p < l.size()) ans+= l.size()-p;
		}
		for(int i = 0; i <n; i++)
		{
			long t = 0;
			while(i < n && dig[i]==0)
			{
				i++;
				t++;
			}
			if(t>0)
			{
				zeros += (t+1)*t/2;
				i--;
			}
		}
		if(b==0) out.println(zeros);
		else if(b==k-1) out.println(ans-zeros);
		else out.println(ans);
	}
	public static void main(String[] args) throws NumberFormatException, IOException 
	{
		new E();
	}
	String nextToken() throws IOException
	{
		if(tok ==null || !tok.hasMoreTokens()) tok = new StringTokenizer(in.readLine());
		return tok.nextToken();
	}
	int nextInt() throws NumberFormatException, IOException
	{
