            if (board[i][j] == '.') {
                dotFound = true;
                if (checkOtherLoc(board, i, j, n)) {
                    res = true;
                    board[i][j] = '#';
                    board[i + 1][j] = '#';
                    board[i][j + 1] = '#';
                    board[i - 1][j] = '#';
                    board[i][j - 1] = '#';
                    res = res & check(board, n);
                }
            }
        }
    }
    if (!dotFound) {
        return true;
    }

    return res;
}

bool checkOtherLoc(vector<string>& board, int i, int j, int n) {
    if (board[i - 1][j] == '.' && board[i + 1][j] == '.' && board[i][j - 1] == '.' && board[i][j + 1] == '.') {
        return true;
    }
    return false;
}
