	class Segment {
		public int low;
		public int high;
		public int man;
	}

	public void run() {
		int n = in.readInt(); // right side
		int m = in.readInt(); // left side

		Segment[] segs = new Segment[m];
		for (int l = 0; l < m; l++) {
			int r = n-in.readInt();
			int c = in.readInt()-1;
			segs[l] = new Segment();
			segs[l].low = Math.min(r,c);
			segs[l].high = Math.max(r,c);
			segs[l].man = l;
