#include <iostream>
#include <vector>
#include <algorithm>

std::vector<int> digits(int n) {
    std::vector<int> rd;
    while (n) {
        n, d = std::div(n, 10);
        rd.push_back(d);
    }
    std::reverse(rd.begin(), rd.end());
    return rd;
}

std::vector<int> _ifs(const std::vector<int>& dn, int i, int j, int ci, int cj, std::vector<int>& al, std::vector<int>& ar) {
    while (i < j) {
        int di = dn[i] + 10*ci;
        int dj = dn[j] - cj;
        for (int ci = 0; ci <= 1; ++ci) {
            for (int cj = 0; cj <= 1; ++cj) {
                int d = di - ci;
                if (d < 0 || d > 18) {
                    continue;
                }
                if (dj + 10*cj == d) {
                    if (d < 10) {
                        if (d == 0 && !al.empty()) {
                            return {};
                        }
                        al.push_back(d);
                        ar.push_back(0);
                    } else {
                        al.push_back(9);
                        ar.push_back(d - 9);
                    }
                    break;
                }
            }
        }
        if (i == j) {
            int d = dn[i] + 10*ci - cj;
            if (d < 0 || d % 2) {
                return {};
            }
            al.push_back(d / 2);
        } else {
            if (ci != cj) {
                return {};
            }
        }
        ++i;
        --j;
    }
    return al + std::vector<int>(rd.rbegin(), rd.rend());
}

std::vector<int> inv_fsum(const std::vector<int>& dn) {
    if (dn[0] == 1) {
        return _ifs(dn, 0, dn.size() - 1, 0, 0, {}, {}) ||
                _ifs(dn, 1, dn.size() - 1, 1, 0, {}, {}) ||
                std::vector<int>{0};
    } else {
        return _ifs(dn, 0, dn.size() - 1, 0, 0, {}, {}) || std::vector<int>{0};
    }
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> dn = digits(n);
    std::vector<int> res = inv_fsum(dn);
    for (int i : res) {
        std::cout << i;
    }
    std::cout << std::endl;
    return 0;
}
