    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        char[][] mat = new char[n+2][n+2];
        for (int i = 0; i < n+2; i++) {
            mat[i][0] = 'x';
            mat[i][n+1] = 'x';
        }
        for (int i = 0; i < n; i++) {
            mat[0][i+1] = 'x';
            mat[n+1][i+1] = 'x';
        }
        for (int i = 1; i <= n; i++) {
            String s = sc.next();
            for (int j = 1; j <= n; j++) {
                mat[i][j] = s.charAt(j-1);
            }
        }
        String output = "YES";
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (output.equals("NO")) {
                    break;
                }
                int s = 0;
                if (mat[i][j+1] == 'o') {
                    s++;
                }
                if (mat[i][j-1] == 'o') {
                    s++;
                }
                if (mat[i+1][j] == 'o') {
                    s++;
                }
                if (mat[i-1][j] == 'o') {
                    s++;
                }
                if (s%2 == 1) {
                    output = "NO";
                    break;
                }
            }
        }
        System.out.println(output);
    }
}
