    static class BPaintingTheWall {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.readInt();
            int m = in.readInt();

            int[][] wall = new int[n][n];
            for (int i = 0; i < m; i++) {
                int r = in.readInt() - 1;
                int c = in.readInt() - 1;

                wall[r][c] = 1;
            }
            int blankrow = 0, blankcol = 0;
            for (int i = 0; i < n; i++) {
                int cnt1 = 0, cnt2 = 0;
                for (int j = 0; j < n; j++) {
                    if (wall[i][j] == 1) cnt1++;
                    if (wall[j][i] == 1) cnt2++;
                }
                if (cnt1 == 0) blankrow++;
                if (cnt2 == 0) blankcol++;
            }
            double[][] dp = new double[n + 1][n + 1];
            dp[0][0] = 0;

            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    if (i == 0 && j == 0) continue;
                    double sum = n * n;
                    if (i > 0 && j > 0) sum += dp[i - 1][j - 1] * i * j;
                    if (i > 0) sum += dp[i - 1][j] * i * (n - j);
                    if (j > 0) sum += dp[i][j - 1] * j * (n - i);
                    dp[i][j] = sum / (n * n - (n - i) * (n - j));
                }
            }
            out.println(dp[blankrow][blankcol]);
        }

    }

