class Pair implements Comparable<Pair>{
    public int x, y;

    Pair(int _x, int _y){
        x = _x;
        y = _y;
    }

    public String toString(){
        return x + "," + y;
    }

    public int compareTo(Pair p){
        if(x != p.x) return x < p.x ? -1 : 1;
        else if(y != p.y) return y < p.y ? -1 : 1;
        return 0;
    }
}

class Group implements Comparable<Group>{
    public int[] low, high;
    public int size;
    public static int k;

    Group(int[] a){
        low = new int[k];
        high = new int[k];
        for(int i = 0; i < k; i++){
            low[i] = a[i];
            high[i] = a[i];
        }
        size = 1;
    }

    public int compareTo(Group g){
        return low[0] - g.low[0];
    }

    public void merge(Group g){
        for(int i = 0; i < k; i++){
            low[i] = Math.min(low[i], g.low[i]);
            high[i] = Math.max(high[i], g.high[i]);
        }
        size += g.size;
    }

    public String toString(){
        return Arrays.toString(low) + "," + Arrays.toString(high);
    }
}



