    int[] grundy = new int[1 << 20];
    int[][] seg = new int[25][];
    int find(int s, int d, int i0, int i1) {
        int len = grundy.length >> d;
        int e = s + len;
        if (e - 1 < i0 || i1 < s) {
            return 0;
        } else if (i0 <= s && e - 1 <= i1) {
            return seg[d][s / len];
        } else {
            return find(s, d + 1, i0, i1) | find((s + e) / 2, d + 1, i0, i1);
        }
    }
    void add(int idx) {
        int s = 0;
        int d = 0;
        int gm = 1 << grundy[idx];
        while (true) {
            int len = grundy.length >> d;
            if (seg[d] == null) {
                seg[d] = new int[grundy.length / len];
            }
            seg[d][s / len] |= gm;

            d++;
            len /= 2;
            if (len == 0) {
                break;
            }
            int e = s + len;
            if (e <= idx) {
                s = e;
                e = s + len;
            }
        }
    }
