            int i1 = (int) Math.floor(Math.sqrt(i));
            int mask = find(0, 0, i0, i1);

            for (int jj = 0;; jj++) {
                if ((mask >> jj & 1) == 0) {
                    grundy[i] = jj;
                    break;
                }
            }
            add(i);
        }

        int xor = 0;
        for (int i = 0; i < n; i++) {
            int g;
            if (a[i] < grundy.length) {
                g = grundy[(int) a[i]];
