class TaskC {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int count = in.readInt();
        int k = in.readInt();
        int[] A = new int[count];
        for (int i = 0; i < count; i++)
            A[i] = in.readInt() + 1000000000;

        A = radixSort(A);

        long[] sum = new long[count + 1];
        for (int i = 1; i <= count; i++)
            sum[i] = sum[i - 1] + A[i - 1];

        int p = 0;
        long maxIndex = 0;
        long maxValue = 0;

        for (int i = 0; i < count; i++) {
            while (p <= i) {
                long v = (long)A[i] * (i - p + 1) - (sum[i + 1] - sum[p]);
                if (v <= k)
                    break;
                p++;
            }

            if (i - p + 1 > maxValue) {
                maxValue = i - p + 1;
                maxIndex = A[i];
            }
        }

        out.printLine(maxValue + " " + (maxIndex - 1000000000));
    }

    private int[] radixSort(int[] f) {
        int[] to = new int[f.length];
        {
            int[] b = new int[65537];
            for(int i = 0;i < f.length;i++)b[1+(f[i]&0xffff)]++;
            for(int i = 1;i <= 65536;i++)b[i]+=b[i-1];
