        else rnd = alen*blen;
        int numofrounds = 0;
        for (int i = 0; i < n; i++) {
            //System.out.println(i, rnd);
            if (i == rnd) {
                numofrounds = n/rnd;
                // System.out.println(numofrounds);
                nik *= numofrounds;
                pol *= numofrounds;
                break;
                //System.out.println(a[ai%alen], b[bi%blen]);
            }
