    if (cur > 1) {
      if (l >= N) {
        dp[cur] = exp - dp[cur];
      } else {
        dp[cur] = Math.min(dfs(l), dfs(r));
        dp[l] -= dp[cur];
        dp[r] -= dp[cur];
