	final long mod = (long) (1e9 + 7);

	void solve() {
		int n = in.nextInt(), k = in.nextInt();
		char[] c = in.next().toCharArray();
		long[] prev = new long[k];
		int[] last = new int[k];
		Arrays.fill(last, -1);
		long sum = 0;
		for (int i = 0; i < c.length; i++) {
			int id = c[i] - 'a';
			prev[id] = (1 + sum) % mod;
			last[id] = i;
			sum = 0;
			for (int j = 0; j < k; j++) {
				sum += prev[j];
			}
		}
		for (int i = c.length; i < c.length + n; i++) {
			int minId = 0;
			for (int j = 0; j < k; j++) {
				if (last[j] < last[minId]) {
					minId = j;
				}
			}
			prev[minId] = (1 + sum) % mod;
			last[minId] = i;
			sum = 0;
			for (int j = 0; j < k; j++) {
				sum += prev[j];
			}
		}
		out.println((1 + sum) % mod);
	}

	void run() {
