import java.util.*;
import java.io.*;

public class C {
	FastScanner in;
	PrintWriter out;

	public void solve() throws IOException {
		int n = in.nextInt(), m = in.nextInt();
		if (m == 1) {
			out.println(1);
			return;
		}
		int[] x = new int[n];
		int sum = 0;
		for (int i = 0; i < n; i++) {
			x[i] = in.nextInt();
			sum += x[i];
		}
		int maxCnt = n * m;
		double[][] p = new double[n + 1][maxCnt + 1];
		p[0][0] = 1;
		for (int i = 0; i < n; i++) {
			double cur = 0;
			for (int j = 1; j <= maxCnt; j++) {
				cur += p[i][j - 1];
				if (j > m) {
					cur -= p[i][j - m - 1];
				}
				if (j >= x[i]) {
					cur -= p[i][j - x[i]];
				}

				p[i + 1][j] += cur / (m - 1);

				if (j >= x[i]) {
					cur += p[i][j - x[i]];
				}
			}
		}
		double pp = 0;
		for (int i = 0; i < sum; i++) {
			pp += p[n][i];
		}
		out.println(pp * (m - 1) + 1);
	}

	public void run() {
		try {
			in = new FastScanner();
			out = new PrintWriter(System.out);

			solve();

			out.close();
		} catch (IOException e) {
			e.printStackTrace();
		}
	}

	class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}
	}

	public static void main(String[] arg) {
		new C().run();
	}
}

