int main() {
    int N;
    std::cin >> N;
    std::vector<std::pair<int, int>> itvs(N);
    for (int i = 0; i < N; i++) {
        int x, w;
        std::cin >> x >> w;
        itvs[i] = std::make_pair(x - w, x + w);
    }
    std::sort(itvs.begin(), itvs.end(), [](const auto& a, const auto& b) {
        return a.second < b.second;
    });

    int ans = 0;
    int end = -(1000000001);
    for (const auto& itv : itvs) {
        if (end <= itv.first) {
            ans++;
            end = itv.second;
        }
    }
    std::cout << ans << std::endl;
    return 0;
}
