import java.io.*;
import java.util.*;
import java.math.*;

public class Main{
    static class Trial implements Comparable<Trial>{
        boolean[] t;
        int r;
        Trial(boolean[] t, int r){
            this.t = t;
            this.r = r;
        }
        public int compareTo(Trial b){
            return this.r-b.r;
        }
    }

    static Trial[] trial;
    static int n,m;
    static int cnt = 0;
    static int r;
    static int[] word;
    static void comb(int p1, int p2){
        if(p2==r){
            boolean[] temp = trial[0].t.clone();
            for(int i=0; i<temp.length; i++)
                temp[i] = !temp[i];
            for(int i=0; i<word.length; i++)
                temp[word[i]] = !temp[word[i]];
            // System.out.println(Arrays.toString(temp));
            int i;
            for(i=1; i<m; i++)
                if(!isValid(temp, trial[i].t, trial[i].r))
                    break;
            cnt = i==m?cnt+1:cnt;
            return;
        }
        for(int i=p1; i<=n-(r-p2); i++){
            word[p2] = i;
            comb(i+1, p2+1);
        }
    }

    static boolean isValid(boolean[] a, boolean[] b, int diff){
        int cnt = 0;
        for(int i=0; i<n; i++)
            if(a[i]==b[i])
                cnt++;
        return cnt==diff;
    }
    public static void main(String[] args)throws Throwable{
        Escanner sc = new Escanner();
        out = new PrintWriter(System.out);
        ///////////
        n = sc.nextInt();
        m = sc.nextInt();
        trial = new Trial[m];

        for(int i=0; i<m; i++){
            String s = sc.nextStr();
            boolean[] t = new boolean[n];
            for(int j=0; j<n; j++)
                t[j] = s.charAt(j)=='1';
            trial[i] = new Trial(t, sc.nextInt());
        }

        Arrays.sort(trial);
        r = trial[0].r;
        word = new int[r];
        comb(0,0);
        out.println(cnt);
        //////////
        out.close();
    }

    static class Escanner {
        BufferedReader in;
        StringTokenizer st;

        Escanner() throws Throwable {
            in = new BufferedReader(new InputStreamReader(System.in),32768);
            st = new StringTokenizer("");
        }

        String nextStr() throws Throwable {
            while(!st.hasMoreTokens())
                st = new StringTokenizer(in.readLine());
            return st.nextToken();
        }

        int nextInt() throws Throwable {
            return Integer.parseInt(nextStr());
        }

        long nextLong() throws Throwable {
            return Long.parseLong(nextStr());
        }

        BigInteger nextBigInt() throws Throwable {
            return new BigInteger(nextStr());
        }

        double nextDouble() throws Throwable {
            return Double.parseDouble(nextStr());
        }
    }
    static PrintWriter out;
}

