public class Solution {
    public static int maximum_wins(int a1, int a2, int a3, int rock, int scissor, int paper) {
        int ans = 0;
        int mini1 = Math.min(a1, scissor);
        ans += mini1;
        scissor -= mini1;
        int mini2 = Math.min(a2, paper);
        ans += mini2;
        paper -= mini2;
        int mini3 = Math.min(a3, rock);
        rock -= mini3;
        ans += mini3;
        return ans;
    }

    public static int minimum_wins(int rock, int paper, int scissor, int a1, int a2, int a3) {
        return Math.max(0, a1 - paper - rock) + Math.max(0, a2 - rock - scissor) + Math.max(0, a3 - paper - scissor);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int a1 = sc.nextInt();
        int a2 = sc.nextInt();
        int a3 = sc.nextInt();
