		FastScanner sc = new FastScanner();
		n = sc.nextInt();
		long time = 0;
		long size = 0;
		long largestSize = 0;
		int[] remain = new int[n+1];
		int[] jobsArrive = new int[n+1];
		int[] jobsLength = new int[n+1];
		for(int i=0;i<n;i++){
			jobsArrive[i] = sc.nextInt();
			jobsLength[i] = sc.nextInt();
		}
