		time = jobsArrive[0];
		remain[0] = jobsLength[0];
		size = jobsLength[0];
		largestSize = size;
		int lastTask = 0;
		int curTask = 0;
		while(curTask != n){
			largestSize = Math.max(size, largestSize);
			long consumption = Math.min(remain[curTask], jobsArrive[lastTask+1]-time);
			size -= consumption;
			time += consumption;
			remain[curTask] -= consumption;
			if(remain[curTask] == 0){
				curTask++;
