#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::vector<std::pair<int, int>> segments;
    int minl = 1000000000;
    int maxr = 0;

    for (int i = 0; i < n; i++) {
        int a, b;
        std::cin >> a >> b;
        segments.push_back({a, b});
        if (a < minl) {
            minl = a;
        }
        if (b > maxr) {
            maxr = b;
        }
    }

    if (std::find(segments.begin(), segments.end(), std::make_pair(minl, maxr)) != segments.end()) {
        std::cout << std::find(segments.begin(), segments.end(), std::make_pair(minl, maxr)) - segments.begin() + 1 << std::endl;
    } else {
        std::cout << -1 << std::endl;
    }

    return 0;
}
