            while(i<n){
                char ch=s.charAt(i);
                int g=i;
                while(i<n&&s.charAt(i)==ch){
                    i++;
                }
                ArrayList<Integer> l=new ArrayList<>();
                for(int j=g;j<i;j++){
                    l.add(arr[j]);
                }
                Collections.sort(l,Collections.reverseOrder());
                for(int j=0;j<Math.min(l.size(),k);j++){
                    sum+=l.get(j);
                }
