	public static void main (String[] args)
	{
		Scanner in= new Scanner(System.in);
		int x=in.nextInt(); 
		int y=in.nextInt();
		int tmp = x - 1;
		BigInteger sum = BigInteger.valueOf(0);

		for(int i=0;i<x;i++)
		{
