import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] names = new String[n];
        for (int i = 0; i < n; i++) {
            names[i] = sc.next();
        }
        System.out.println(newProblem(names));
    }

    static String newProblem(String[] names) {
        for (int i = 1; i <= 3; i++) {
            for (String s : getPermutations(i, "abcdefghijklmnopqrstuvwxyz")) {
                if (isValid(s, names)) {
                    return s;
                }
            }
        }
        return "";
    }

    static boolean isValid(String s, String[] names) {
        for (String name : names) {
            if (name.contains(s)) {
                return false;
            }
        }
        return true;
    }

    static List<String> getPermutations(int n, String str) {
        List<String> result = new ArrayList<>();
        if (n == 1) {
            for (char c : str.toCharArray()) {
                result.add(String.valueOf(c));
            }
            return result;
        }
        for (char c : str.toCharArray()) {
            List<String> sub = getPermutations(n - 1, str.replace(String.valueOf(c), ""));
            for (String s : sub) {
                result.add(c + s);
            }
        }
        return result;
    }
}
