import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] pts = new String[n];
        for (int i = 0; i < n; i++) {
            pts[i] = sc.next();
        }
        System.out.println(centre(n, pts));
    }

    public static String centre(int n, String[] pts) {
        double x = 0, y = 0;
        for (int j = 7; j <= 65537; j++) {
            if (gcd(n, j) == 1) {
                for (int i = 0; i < n; i++) {
                    int k = Integer.parseInt(pts[i]);
                    x += k * Math.cos(2 * Math.PI * i * j / n);
                    y += k * Math.sin(2 * Math.PI * i * j / n);
                }
                if (!(Math.abs(x) < 0.000001 && Math.abs(y) < 0.000001)) {
                    return "NO";
                }
            }
        }
        return "YES";
    }

    public static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}
