public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        if (m > limit(n)) {
            System.out.println(-1);
            return;
        }

        if (m == 0) {
            int[] ans = new int[n];
            for (int i = 0; i < n; i++) {
                ans[i] = 1000000001;
            }
            for (int i = 0; i < n; i++) {
                System.out.print(ans[i] + " ");
            }
            return;
        }

        int L = 3;
        int R = n + 1;
        while (L + 1 < R) {
            int k = (L + R) / 2;
            if (limit(k) > m) {
                R = k;
            } else {
                L = k;
            }
        }
        k = L;
        int[] ans = new int[k];
        for (int i = 0; i < k; i++) {
            ans[i] = i + 1;
        }

        int req = m - limit(k);
        if (req > 0) {
            ans[k - 1] += req;
            k++;
        }

        for (int i = k; i < n; i++) {
            ans[i] = 1000000001;
        }

        for (int i = 0; i < n; i++) {
            System.out.print(ans[i] + " ");
        }
    }

    static int limit(int n) {
        if (n < 3) {
            return 0;
        }
        if (n % 2 == 1) {
            return (n - 1) * (n - 1) / 2;
        } else {
            return (n - 2) * n / 2;
        }
    }
}
