class TaskC {
    <T extends Comparable<T>> T min(T [] A) {
        return A[imin(A)];
    }

    <T extends Comparable<T>> int imin(T [] A) {
        int res = 0, N = A.length;
        for (int i = 1; i < N; ++i)
            if (A[i].compareTo(A[res]) < 0)
                res = i;
        return res;
    }
    public void solve(int testNumber, FastScanner s, Output ww) {
        try{
            int N = s.nextInt();
            int X = s.nextInt() - 1;
            Long [] A = new Long[N];
            for(int i=0;i<N;i++)  A[i] = s.nextLong();

            long M = min(A), C = 0;
            int W; for (W = X; A[W] != M; --W) {
                --A[W]; ++C;
                if (W == 0)
                    W = N;
            }
            A[W] += C;

            for (int i = 0; i < N; ++i)
                A[i] -= M;
            A[W] += M * N;

            for(Long i : A) ww.print(i+" ");

        }catch(Exception e){
            e.printStackTrace();
        }
    }
}

class FastScanner {
    BufferedReader s;
    StringTokenizer st;

    public FastScanner(InputStream InputStream){
        st = new StringTokenizer("");
        s = new BufferedReader(new InputStreamReader(InputStream));
    }

    public FastScanner(File f) throws FileNotFoundException{
        st = new StringTokenizer("");
        s = new BufferedReader (new FileReader(f));
    }

    public int nextInt() throws IOException{
        if(st.hasMoreTokens())
            return Integer.parseInt(st.nextToken());
        else{
            st = new StringTokenizer(s.readLine());
            return nextInt();
        }
    }

    public long nextLong() throws IOException{
        if(st.hasMoreTokens())
            return Long.parseLong(st.nextToken());
        else{
            st = new StringTokenizer(s.readLine());
            return nextLong();
        }
    }

}

class Output {

    private final PrintWriter writer;

    public Output(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public Output(Writer writer) {
        this.writer = new PrintWriter(writer);
    }

    public void print(Object...objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0)
                writer.print(' ');
            writer.print(objects[i]);
        }
    }

    public void close() {
        writer.close();
    }


