        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();
        int ans = 0;
        Map<Integer, Integer> seen = new HashMap<>();

        for (int i = 1; i <= a; i++) {
            for (int j = 1; j <= b; j++) {
                for (int k = 1; k <= c; k++) {
                    int p = i * j * k;
                    if (seen.containsKey(p)) {
                        ans = (ans + seen.get(p)) % 1073741824;
