    static int solve(int x, int y, int z) {
        Map<Integer, Integer> d = new HashMap<>();
        for (int p = 2; p <= 100; p++) {
            d.put(p, 0);
        }

        for (int p = 2; p <= 100; p++) {
            if (p > x && p > y && p > z) {
                break;
            }
            while (x % p == 0) {
                x /= p;
                d.put(p, d.get(p) + 1);
