import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[][] pc = new int[n][2];
        int[] party_votes = new int[m];
        for (int i = 0; i < n; i++) {
            pc[i][0] = sc.nextInt() - 1;
            pc[i][1] = sc.nextInt();
            party_votes[pc[i][0]]++;
        }
        Arrays.sort(pc, (a, b) -> a[1] - b[1]);
        int min_cost = Integer.MAX_VALUE;
        for (int votes = 0; votes <= n; votes++) {
            int[] _party_votes = party_votes.clone();
            boolean[] dangerous = new boolean[m];
            boolean[] used = new boolean[n];
            int cur_cost = 0;
            for (int i = 0; i < n; i++) {
                if (dangerous[pc[i][0]] && pc[i][0] != 0) {
                    cur_cost += pc[i][1];
                    _party_votes[0]++;
                    _party_votes[pc[i][0]]--;
                    dangerous[pc[i][0]] = _party_votes[pc[i][0]] >= votes;
                    used[i] = true;
                }
            }
            for (int i = 0; i < n; i++) {
                if (_party_votes[0] >= votes) {
                    break;
                }
                if (!used[i]) {
                    _party_votes[0]++;
                    cur_cost += pc[i][1];
                }
            }
            min_cost = Math.min(min_cost, cur_cost);
        }
        System.out.println(min_cost);
    }
}
