import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int g = 0;
        for (int x : a) {
            g = gcd(g, x - 1);
        }

        int answer = 0;

        for (int i = 1; i <= g; i++) {
            if (i * i > g) {
                break;
            }
            if (g % i != 0) {
                continue;
            }
            process(i);
            if (i * i != g) {
                process(g / i);
            }
        }

        System.out.println(answer);
    }

    static int gcd(int x, int y) {
        while (y != 0) {
            x = x % y;
            y = x;
        }
        return x;
    }

    static void process(int x) {
        if (x % 2 == 0) {
            return;
        }
        for (int i = 30; i >= 0; i--) {
            int v = (int) (Math.pow(2, i) * x);
            if (v > m) {
                break;
            }
            answer += m - v;
        }
    }
}
