        int n = sc.nextInt();
        int[] ar = new int[n];
        for (int i = 0; i < n; i++) {
            ar[i] = sc.nextInt();
        }
        Stack<Pair<Long, Integer>> st = new Stack<>();
        for (int i = 0; i < n; i++) {
            long ss = ar[i];
            int c = 1;
            while (st.size() && (st.peek().first * c > ss * st.peek().second)) {
                ss += st.peek().first;
                c += st.peek().second;
                st.pop();
            }
            st.push(new Pair<>(ss, c));
        }
        double[] ans = new double[n];
        while (st.size()) {
            for (int i = n - 1; i >= n - st.peek().second; i--) {
                ans[i] = (double) st.peek().first / (double) st.peek().second;
            }
            n -= st.peek().second;
            st.pop();
        }
        for (int i = 0; i < n; i++) {
            System.out.printf("%.12f\n", ans[i]);
        }
    }
}
