class TaskC {


    void solve(InputReader in, OutputWriter out) {
        long a = in.nextLong();
        long b = in.nextLong();
        long c = in.nextLong();
        long l = in.nextLong();

        long all = (l+1)*(l+2)*(l+3) / 6;

        all -= bad(a,b,c,l);
        all -= bad(b,c,a,l);
        all -= bad(c,a,b,l);


        out.printLine(all);
    }

    private long bad(long a, long b, long c, long l) {
        long val = 0;
        for(int i=0;i<=l;i++) {
            long fixedSide = a + i;
            long rest = l - i;
            long twoSides = b + c;
            if(fixedSide < twoSides) continue;
            long diff = fixedSide - twoSides;
            rest = Math.min(rest, diff);
            val += ((rest+1) * (rest+2) / 2);
        }
        return val;
    }


}
