    int n, m;
    cin >> n >> m;
    vector<int> x(n);
    vector<int> p(m);
    for (int i = 0; i < n; i++) cin >> x[i];
    for (int i = 0; i < m; i++) cin >> p[i];
    vector<int> dx(n - 1);
    for (int i = 0; i < n - 1; i++) dx[i] = x[i + 1] - x[i];
    int d = dx[0];
    for (int i = 0; i < n - 1; i++) d = gcd(d, dx[i]);
    for (int i = 0; i < m; i++) {
