        if (k > n) {
            return "NO";
        }
        int current = 0;
        for (int i = 0; i < n; i++) {
            if (S.charAt(i) == 'N') {
                current++;
                if (current > k) {
                    return "NO";
                }
            } else {
                current = 0;
            }
        }
        boolean startWork = true;
        for (int i = 0; i < k; i++) {
            if (S.charAt(i) == 'Y') {
                startWork = false;
            }
        }
        if (startWork && (k == n || k < n && S.charAt(k) != 'N')) {
            return "YES";
        }
        if (n == 1) {
            if (k == 1 && S.charAt(0) == '?N') {
                return "YES";
            }
            if (k == 0 && S.charAt(0) == '?Y') {
                return "YES";
            }
            return "NO";
        }
        if (k == n) {
            if (S.contains("Y")) {
                return "NO";
            }
            return "YES";
        }
        int Y_count = 0;
        int p1 = 0;
        for (int i = 1; i <= k; i++) {
            if (S.charAt(i) == 'Y') {
                Y_count++;
            }
        }
        int p2 = i;
        for (int i = k + 1; i < n; i++) {
            if (Y_count == 0 && S.charAt(p1) != 'N' && (p2 == n - 1 || S.charAt(p2 + 1) != 'N')) {
                return "YES";
            }
            p1++;
            p2++;
            if (p2 < n && S.charAt(p2) == 'Y') {
                Y_count++;
            }
            if (p1 < n && S.charAt(p1) == 'Y') {
                Y_count--;
            }
        }
        if (Y_count == 0 && p1 < n && S.charAt(p1) != 'N') {
            return "YES";
        }
        return "NO";
    }
}
