  }
  long long deg[n];
  memset(deg, 0, sizeof deg);
  sort(a.begin(), a.end());
  for (int i = 0; i < n; i++)
    for (int j = i + 1; j < n; j++)
      if (dist(a[i].second, a[j].second) <= sqr(a[j].first) && i != j) deg[i]++;
  double answer = 0.0;
  for (int i = 0; i < n; i++) {
    answer += (double)acos(-1) * a[i].first * a[i].first * func(deg[i]);
  }
  printf("%.20lf\n", answer);
  return 0;
}


