public class cf264b {
  public static void main(String[] args) {
    FastScanner in = new FastScanner(System.in);
    int n = in.nextInt();
    int MAX = 100000;
    ArrayList<Integer>[] divs = new ArrayList[MAX+1];
    for(int i=0; i<=MAX; i++)
      divs[i] = new ArrayList<Integer>();
    for(int i=2; i<=MAX; i++)
      for(int j=i+i; j<=MAX; j+=i)
        divs[j].add(i);
    int ans = 1;
    int[] dp = new int[MAX+1];
    int[] dp2 = new int[MAX+1];
    Arrays.fill(dp,1);
    Arrays.fill(dp,1);
    for(int i=0; i<n; i++) {
      int x = in.nextInt();
      for(int y : divs[x])
