  for (int u = 0; u < N - 1; ++u) {
    cin >> v;
    graph[u + 1].push_back(v);
    graph[v].push_back(u + 1);
  }
  for (int i = 0; i < N; ++i) cin >> c[i];
  dfs(0, -1);
  cout << f[0][1] << endl;
  return 0;
}


