using namespace std;

typedef long long ll;
typedef pair<ll, ll> pll;
typedef pair<double, double> pdd;

const int INF = 1e9;
const double EPS = 1e-9;

double dist(pll a, pll b) {
    return sqrt((a.first - b.first) * (a.first - b.first) + (a.second - b.second) * (a.second - b.second));
}

double minh(pll a, pll b, pll c) {
    double m = dist(a, b);
    double n = dist(b, c);
    double k = dist(a, c);
    double p = (m + n + k) / 2;
    double sqp = sqrt((p * (p - m) * (p - n) * (p - k)));
    double hm = (2 / m) * sqp;
    double hn = (2 / n) * sqp;
    double hk = (2 / k) * sqp;
    return min(hm, hn, hk);
}

void solve() {
    int n;
    cin >> n;
    vector<pll> coords(n);
    for (int i = 0; i < n; i++) {
        cin >> coords[i].first >> coords[i].second;
    }
    coords.insert(coords.end(), coords.begin(), coords.end());

    double res = min(
        minh(coords[i], coords[i + 1], coords[i + 2])
        for (int i = 0; i < n));

    cout << fixed << setprecision(9) << res / 2 << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    solve();

    return 0;
}
