#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n, k, x;
    std::cin >> n >> k >> x;
    std::vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) {
        std::cin >> a[i];
    }

    int lo = 0, hi = 1e9 * 5000;
    std::vector<std::pair<int, int>> q(n + 1);

    auto get = [&](int mid) {
        int f = 0, r = 0;
        q[0] = {0, 0, 0};
        for (int i = 1; i <= n; i++) {
            if (q[r].second == i - k - 1) r++;
            cur = {q[r].first + a[i] - mid, q[r].second + 1, i};
            while (r <= f && q[f] <= cur) f--;
            f++;
            q[f] = cur;
        }
        if (q[r].second == n - k) r++;
        return q[r];
    };

    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        auto [sm, cnt, _] = get(mid);
        if (cnt >= x) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }

    auto [sm, cnt, _] = get(lo);
    int ans = std::max(-1, sm + x * lo);
    std::cout << ans << std::endl;

    return 0;
}
