        L[a].push_back(b);
        L[b].push_back(a);
    }
    if(n!=1){
        queue<int>q;
        q.push(1);
        vector<int>D(n+1,-1);
        D[1]=0;
        while(!q.empty()){
            int t=q.front();
            q.pop();
            for(int x:L[t]){
                if(D[x]==-1||D[x]>D[t]+1){
                    q.push(x);
                    D[x]=D[t]+1;
                }
            }
        }
        cout<<D[n]<<endl;
