        vector<vector<int>>M(n+1);
        for(int i=1;i<=n;i++){
            L[i].push_back(0);
            L[i].push_back(n+1);
            sort(L[i].begin(),L[i].end());
            for(int j=0;j<L[i].size()-1;j++){
                for(int v=L[i][j]+1;v<L[i][j+1];v++){
                    if(v!=i){
                        M[i].push_back(v);
