import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	static boolean prefixCompare(char[] a,int i,int j)
	{
		if(i > j-i+1)return true;
		if(i < j-i+1)return false;
		for (int x = 0; x < i; x++) 
		{
			if(a[x]<a[x+i])return false;
			if(a[x]>a[x+i])return true;
		}
		return true;
	}
	public static void main(String[] args) throws Throwable {
		Scanner sc = new Scanner(System.in);
		char[] a = sc.nextLine().toCharArray();
		int ans = 0;
		for(int i = a.length-1;i>=0;--i)
		{
			++ans;
			int j = i;
			if(a[i]=='0') 
				while(j>0 && a[--j]=='0');
			if(prefixCompare(a, j, i))i=j;
			else break;
		}
		System.out.println(ans);		
	}
	static class Scanner 
	{
		StringTokenizer st;
		BufferedReader br;
		public Scanner(InputStream s){	br = new BufferedReader(new InputStreamReader(s));}
		public Scanner(String file) throws FileNotFoundException { br = new BufferedReader(new FileReader(file));}
		public String next() throws IOException 
		{
			while (st == null || !st.hasMoreTokens())st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}
		public int nextInt() throws IOException {return Integer.parseInt(next());}
		public long nextLong() throws IOException {return Long.parseLong(next());}
		public String nextLine() throws IOException {return br.readLine();}
		public double nextDouble() throws IOException
		{
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if(x.charAt(0) == '-'){neg = true;start++;}
			for(int i = start; i < x.length(); i++)
				if(x.charAt(i) == '.')
				{
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				}
				else{sb.append(x.charAt(i));if(dec)f *= 10;}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg?-1:1);
		}
		public int[] nexIntArray() throws Throwable
		{
			st = new StringTokenizer(br.readLine());
			int[] a = new int[st.countTokens()];
			for(int i = 0; i < a.length;i++)a[i]=nextInt();
			return a;
		}
		public boolean ready() throws IOException {return br.ready();}
	}
