import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        Map<Integer, List<Integer>> map = new HashMap<>();
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            map.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            map.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }
        int cnt = 0;
        while (true) {
            boolean f = false;
            Map<Integer, Boolean> vis = new HashMap<>();
            for (Map.Entry<Integer, List<Integer>> entry : map.entrySet()) {
                if (entry.getValue().size() == 1 && !vis.containsKey(entry.getKey())) {
                    int temp = entry.getValue().get(0);
                    map.get(temp).remove(map.get(temp).indexOf(entry.getKey()));
                    vis.put(entry.getKey(), true);
                    f = true;
                }
            }
            if (!f) break;
            cnt++;
            f = false;
        }
        System.out.println(cnt);
    }
}
