std::vector<std::string> generateRowTilings(int n) {
    std::vector<std::string> tilings;
    for (const auto& (rowNum, firstTile, pattern) : generateRowTilingPatterns(n)) {
        tilings.push_back(makeRowTiling(rowNum, firstTile, pattern, n));
    }
    return tilings;
}

std::vector<std::tuple<int, char, std::string>> generateRowTilingPatterns(int n) {
    std::vector<std::tuple<int, char, std::string>> patterns;
    patterns.push_back({1, 'a', "bbcc"});
    patterns.push_back({2, 'a', "ccbb"});
    patterns.push_back({3, 'd', "deed"});
    patterns.push_back({4, 'e', "edde"});
    return patterns;
}

std::string makeRowTiling(int row, char prefix, const std::string& pattern, int n) {
    std::string tiling = prefix;
    for (int i = 0; i < n - 2; ++i) {
        tiling += pattern[i % 4];
    }
    tiling += pattern[(n - 2) % 4];
    if ((n % 2 != (row - 1) / 2)) {
        tiling += 'f';
    }
    return tiling;
}

int main() {
    int n;
    std::cin >> n;
    computeTiling(n);
    return 0;
}
