std::string rek(int k) {
    if (k == 1) {
        return "a a";
    } else if (k == 2) {
        return "aa a";
    }

    std::string s, p = rek((k - 1) / 2);
    char x = p.back() + 1;

    return p + x * (2 - k % 2) + s.substr(p.size()) + 2 * x;
}

int main() {
    int k;
    std::cin >> k;

    std::string s, p = rek(k);
    std::cout << s << " " << p << std::endl;

    return 0;
}
