int main() {
    int y1, y2, yw, xb, yb, r;
    std::cin >> y1 >> y2 >> yw >> xb >> yb >> r;
    yw -= r;
    y1, y2 = yw * 2 - y2, yw * 2 - y1;

    double xww(double y) {
        return (y - yw) * xb / (y - yb);
    }

    double dd(double y) {
        double xw = xww(y);
        return (y - y1) / hypot(1, (yw - y) / xw);
    }

    double binary_search() {
        double a = y1 + r, b = 1e10;
        for (int i = 0; i < 200; i++) {
            double m = (a + b) / 2;
            if (dd(m) < r) {
                a = m;
            } else {
                b = m;
            }
        }
        return (a + b) / 2;
    }

    double m = binary_search();
    if (m + r > y2) {
        std::cout << "-1" << std::endl;
    } else {
        m = (m + y2 - r) / 2;
        std::cout << xww(m) << std::endl;
    }

    return 0;
}
