        } else {
            n[i] = '1';
            return;
        }
    }
    n.push_front('1');
}

int main() {
    std::deque<char> n(std::cin);
    int ans = 0;

    while (n.size() != 1) {
        if (n.back() == '1') {
            add(n);
        } else {
            n.pop_back();
        }
        ans++;
    }

    std::cout << ans << std::endl;

    return 0;
}
