#include <string>
#include <vector>

int main() {
    int n;
    std::cin >> n;
    std::vector<std::string> array(n);
    for (int i = 0; i < n; i++) {
        std::cin >> array[i];
    }
    int b = n - 2;
    while (b > -1) {
        if (array[b + 1] >= array[b]) {
            b--;
        } else {
            if (array[b].size() > array[b + 1].size()) {
                array[b] = array[b].substr(0, array[b + 1].size());
            }
            array[b] = cut_to_lexicographic(array[b], array[b + 1]);
        }
    }
    for (const auto& s : array) {
        std::cout << s << std::endl;
    }
    return 0;
}

std::string cut_to_lexicographic(const std::string& word_bigger, const std::string& word_smaller) {
    for (int l = 0; l < word_bigger.size(); l++) {
        if (word_bigger[l] != word_smaller[l]) {
            return word_bigger.substr(0, l);
        }
    }
    return word_bigger;
}
