public class A448 implements Runnable {
	private Scanner in = new Scanner(System.in);
	private PrintWriter out = new PrintWriter(System.out);
	private int cup [];
	private int medal [];
	private int shelve;

	int cupSum = 0;
	int medalSum = 0;
	private String ans = "NO";

	public static void main(String[] args) {
		new Thread(new A448()).start();
	}

	private void read() {

		cup = new int[3];
		medal = new int[3];

		for(int i = 0; i < 3; i++){
			cup[i] = in.nextInt();
			cupSum += cup[i];
		}

