		if(cupSum > 5){
			shelve = shelve - (int) Math.ceil((double)cupSum / 5);
		} else if(cupSum > 0){
			shelve = shelve - 1;
		}

		if(medalSum > 10){
			shelve = shelve - (int) Math.ceil((double)medalSum / 10);
		} else if(medalSum > 0){
			shelve = shelve - 1;
		}


		if(shelve >= 0) {
			ans = "YES";
		}



	}

	private void write() {

			out.println(ans);

	}

	public void run() {
